test('Inbox adopts the actual drop zone, note/link forms and inventory without rebinding them',async()=>{
 const b=boot(1,'<section class="material-surface"><div class="material-readiness">Real connection status</div><div class="material-tools"><div class="material-intake flow-drop"><span>Add to this project</span><button data-flow-action="files">Add files</button><input data-files type="file" hidden></div><div class="material-note-tools"><details><summary>Write note</summary><textarea data-draft="note">Earlier note</textarea><button data-flow-action="note">Keep note</button></details><details><summary>Links</summary><textarea data-draft="links">https://example.test</textarea></details></div></div><div class="sws-work-tools"><details><summary>Prepared review</summary>Not connected</details></div><div class="material-layout"><div class="material-index"><nav class="material-inventory"><div class="material-record"><div><strong>Source</strong><span class="small">Invented transcript</span></div><button data-flow-action="history:0">Read</button><details class="material-choice-details"><summary>Details</summary>Original location</details></div></nav></div></div></section>');
 const drop=b.d.querySelector('.flow-drop'),note=b.d.querySelector('[data-draft="note"]'),read=b.d.querySelector('[data-flow-action="history:0"]'),files=b.d.querySelector('[data-files]');let drops=0,reads=0,notes=0;drop.ondrop=e=>{e.preventDefault();drops++;};read.onclick=()=>reads++;b.d.querySelector('[data-flow-action="note"]').onclick=()=>notes++;note.value='Unsaved personal note';b.run();drop.dispatchEvent(new b.w.Event('drop',{cancelable:true}));read.click();b.d.querySelector('[data-flow-action="note"]').click();
 assert.equal(drops,1);assert.equal(reads,1);assert.equal(notes,1);assert.equal(b.d.querySelector('.drop'),drop);assert.equal(b.d.querySelector('[data-files]'),files);assert.equal(note.value,'Unsaved personal note');assert.ok(note.closest('.drop'));assert.ok(read.closest('.mrow'));assert.equal(b.d.querySelectorAll('.thumb').length,1);assert.equal(b.d.querySelectorAll('.wb-intake-status').length,1);assert.equal(b.d.querySelectorAll('.wb-intake-more').length,1);
 let changes=0;const observer=new b.w.MutationObserver(r=>changes+=r.length);observer.observe(b.d.querySelector('#workspace'),{subtree:true,childList:true});b.run();await Promise.resolve();assert.equal(changes,0);observer.disconnect();b.close();
});
test('This piece contact sheet preserves real photo selection, caption/credit saves and used-where actions',async()=>{
 const b=boot(8,'<section data-media-outputs-tools="8"><div class="mot-tool-grid"><details><summary>Footage</summary><textarea>Unsaved request</textarea></details></div></section><section id="owned-photo-stage"><div id="photos"></div></section>');b.w.eval(fs.readFileSync(new URL('../public/document-study/study-photos.js',import.meta.url),'utf8'));
 const record={revision:1,photos:[{sourceId:'invented-photo',name:'Invented.jpg',url:'/invented.jpg',caption:'Saved caption',credit:'Saved credit',selected:false}]},writes=[];let usage=0;
 const owner=b.w.mountPhotosStage(b.d.querySelector('#photos'),{projectId:'invented-project',documentId:'invented-part',request:async(url,body)=>{if(body)writes.push({url,body});return body?{...record,revision:2,photos:[{...record.photos[0],...body}]}:record;},readUsage:async()=>({usageHash:'proof',coverage:{status:'complete'},sources:[{sourceId:'invented-photo',status:'available',occurrences:[{outputName:'Invented article',kind:'article',freshness:{stale:false},location:{slot:'cover'}}]}]}),openUsage:()=>usage++});
 await owner.ready;await Promise.resolve();b.run();const caption=b.d.querySelector('[data-caption]'),credit=b.d.querySelector('[data-credit]'),selected=b.d.querySelector('[data-selected]');caption.value='Exact new caption';caption.dispatchEvent(new b.w.Event('input'));credit.value='Exact new credit';credit.dispatchEvent(new b.w.Event('input'));selected.checked=true;selected.dispatchEvent(new b.w.Event('change'));b.run();assert.equal(b.d.querySelector('[data-caption]'),caption);assert.equal(caption.value,'Exact new caption');assert.equal(credit.value,'Exact new credit');assert.ok(b.d.querySelector('.mgrid .asset>.b .photo-thumb-state'));assert.match(b.d.querySelector('.photo-thumb-state').textContent,/Selected · Edited/);b.d.querySelector('[data-photo-occurrence]').click();assert.equal(usage,1);
 b.d.querySelector('[data-save]').click();await Promise.resolve();await Promise.resolve();assert.equal(writes.length,1);assert.equal(writes[0].body.caption,'Exact new caption');assert.equal(writes[0].body.credit,'Exact new credit');assert.equal(writes[0].body.selected,true);assert.equal(b.d.querySelector('[data-media-outputs-tools]').nextElementSibling.id,'owned-photo-stage','filter owner retains its native sibling');owner.destroy();b.close();
});
