test('Direction keeps Save/status compact and moves existing scoped tools and live Sources into one More disclosure',async()=>{const b=boot(4,'<article id="stage-working-lane"><section class="source-continuation"><header class="source-continuation-header"><select data-source-part><option value="one">One</option></select></header><div class="source-continuation-sources"><button data-live-source>Read exact source</button></div><div data-continuation-direction-mount><div id="material-human-direction"><section class="human-direction-editor"><header><h3>Direction</h3><label>Applies to<select data-direction-scope><option value="part">Part article</option></select></label></header><details class="human-direction-edit"><label class="human-direction-words">Your words<textarea data-human-direction>Exact saved direction</textarea></label><div class="human-direction-actions"><button data-direction-save>Save direction</button><button data-direction-undo>Undo saved change</button><span role="status">Saved for this scope</span></div><p role="alert">Compare recovered words before saving.</p><div class="human-direction-actions"><button data-direction-keep-local>Keep my wording</button></div><p class="small">Saved revision 3</p><details data-direction-history><summary>Saved file &amp; history</summary>Retained history</details></details></section></div></div><footer>Existing source handoff</footer></section></article>');try{const save=b.d.querySelector('[data-direction-save]'),undo=b.d.querySelector('[data-direction-undo]'),scope=b.d.querySelector('[data-direction-scope]'),source=b.d.querySelector('[data-live-source]'),words=b.d.querySelector('textarea');let saved=0,undone=0,opened=0;save.onclick=()=>saved++;undo.onclick=()=>undone++;source.onclick=()=>opened++;words.value='Exact unsaved direction';b.run();const more=b.d.querySelector('[data-direction-more]');assert.ok(more);assert.equal(more.open,false);assert.ok(undo.closest('[data-direction-more]'));assert.ok(scope.closest('[data-direction-more]'));assert.ok(source.closest('[data-direction-more]'));assert.ok(b.d.querySelector('[data-direction-history]').closest('[data-direction-more]'));assert.equal(save.closest('[data-direction-more]'),null);assert.equal(b.d.querySelector('[role="status"]').closest('[data-direction-more]'),null);assert.equal(b.d.querySelector('[role="alert"]').closest('[data-direction-more]'),null);assert.equal(b.d.querySelector('[data-direction-keep-local]').closest('[data-direction-more]'),null);assert.equal(b.d.querySelectorAll('[data-direction-primary-actions]').length,1);assert.equal(b.d.querySelector('[data-direction-keep-local]').parentElement.hasAttribute('data-direction-primary-actions'),false);more.open=true;save.click();undo.click();source.click();assert.deepEqual([saved,undone,opened],[1,1,1]);assert.equal(words.value,'Exact unsaved direction');b.d.querySelector('[data-direction-more-close]').click();assert.equal(more.open,false);assert.equal(b.d.querySelectorAll('.wb-direction-context').length,1);let mutations=0;const observer=new b.w.MutationObserver(rows=>mutations+=rows.length);observer.observe(b.d.querySelector('#workspace'),{subtree:true,childList:true});b.run();await Promise.resolve();assert.equal(mutations,0);observer.disconnect();}finally{b.close();}});

test('saved source analysis stays outside the shared-notes writer and has a direct record entrance',()=>{
 const b=boot(3,'<section class="phaseReader"><article class="flow-paper" id="stage-working-lane"><div id="material-human-direction"><p>Original shared notes</p></div><details class="flow-details flow-prose" data-disclosure="report"><summary>Read source analysis</summary><h2>Saved analysis</h2><p>Exact earlier invented analysis.</p></details><details data-disclosure="brief"><summary>Reusable brief</summary><p>Preserve the generated origin.</p></details></article></section>');
 const record=b.d.querySelector('[data-disclosure="report"]'),shared=b.d.querySelector('#material-human-direction'),words=record.querySelector('p');b.run();
 assert.equal(b.d.querySelector('.wb-research-empty').closest('#material-human-direction'),null,'notes writer must not own the Research surface');
 assert.ok(b.d.querySelector('[data-wb-research-record]'),'saved analysis has a direct entrance even without parsed findings');
 shared.innerHTML='<p>Refreshed shared notes</p>';b.run();
 assert.strictEqual(b.d.querySelector('[data-disclosure="report"]'),record);assert.strictEqual(record.querySelector('p'),words);assert.equal(words.textContent,'Exact earlier invented analysis.');
 b.d.querySelector('[data-wb-research-record]').click();assert.equal(record.tagName,'SECTION');assert.match(b.d.querySelector('.wb-research-count').textContent,/2 records/);b.close();
});

test('Share keeps recipient and exact piece selectors visible with the same input nodes and actions',()=>{const b=boot(11,'<section data-output-stage-surface="11" data-share-connected="true"><header class="oss-heading">Share</header><div class="oss-tool-row"><label>Piece<select data-share-output><option value="exact-article">Current exact Article</option></select></label><label>For<select data-share-recipient><option>Invented recipient</option></select></label><button data-share-action="new-recipient">Add recipient</button></div><div class="oss-field-row"><label>Recipient<input data-share-field="recipient" value="Invented recipient"></label><label>Link<input data-share-field="link" value="https://example.invalid/exact"></label></div><label><textarea data-share-field="message">Unsent invitation</textarea></label><div class="oss-tool-row"><button data-share-action="save">Save invitation</button></div></section>');const input=b.d.querySelector('[data-share-field="recipient"]'),piece=b.d.querySelector('[data-share-output]'),add=b.d.querySelector('[data-share-action="new-recipient"]');let clicked=0;add.onclick=()=>clicked++;b.run();b.run();const section=b.d.querySelector('.wb-share-recipient');assert.equal(section.tagName,'SECTION');assert.equal(section.querySelector('h3').textContent,'Recipient & piece');assert.equal(section.querySelector('summary,details'),null);assert.equal(input.closest('.wb-share-recipient'),section);assert.equal(piece.closest('.wb-share-recipient'),section);assert.equal(section.querySelector('[data-share-field="recipient"]'),input);add.click();assert.equal(clicked,1);assert.equal(input.value,'Invented recipient');assert.equal(b.d.querySelector('[data-share-field="message"]').value,'Unsent invitation');b.close();});

test('first Research record entrance follows the visible replacement node before any second decoration',()=>{
 const b=boot(3,'<div class="research-standard"><details class="research-standard-coverage"><summary>Records</summary><details><summary>RESEARCH - Exact retained.md</summary><pre>Original exact retained analysis.</pre></details></details></div>');try{const record=b.d.querySelector('.research-standard-coverage>section'),words=record.querySelector('pre'),calls=[];record.scrollIntoView=options=>calls.push(options);const action=b.d.querySelector('[data-wb-research-record]');assert.equal(action.textContent,'RESEARCH - Exact retained.md');action.click();assert.equal(calls.length,1);assert.equal(calls[0].block,'start');assert.equal(b.d.activeElement,record.querySelector('h3'));assert.equal(record.querySelector('pre'),words);assert.equal(words.textContent,'Original exact retained analysis.');assert.equal(b.d.querySelectorAll('.research-standard details,.research-standard summary').length,0);}finally{b.close();}
});

test('cloned Research record entrance resolves the same connected owner once without relying on copied onclick',()=>{
 const b=boot(3,'<section class="phaseReader flow-stage"><article class="flow-paper"><div class="research-standard"><section data-research-point="point"><h2>Finding</h2></section></div></article><section class="flow-retained"><h3>Earlier records</h3><section class="phaseReader"><article class="compactRecord"><div class="recordBody"><h1>Exact retained record</h1><p>Exact source words.</p></div></article></section></section></section>');try{const original=b.d.querySelector('[data-wb-research-record]'),copy=original.cloneNode(true),record=b.d.querySelector('.compactRecord'),words=record.querySelector('.recordBody');let reads=0;record.scrollIntoView=()=>reads++;original.replaceWith(copy);assert.equal(copy.onclick,null);copy.click();assert.equal(reads,1);assert.equal(record.dataset.wbResearchSelected,'true');assert.equal(b.d.querySelectorAll('.wb-research-back').length,1);assert.equal(record.querySelector('.recordBody'),words);b.d.querySelector('.wb-research-back').click();assert.equal(record.hasAttribute('data-wb-research-selected'),false);copy.click();assert.equal(reads,2);b.stage(4);copy.click();assert.equal(reads,2);}finally{b.close();}
});

test('selected plain retained Research section is visible and metadata keeps its exact child nodes without a disclosure',()=>{
 const b=boot(3,'<section class="phaseReader flow-stage"><article class="flow-paper"><div class="research-standard"><section data-research-point="point"><h2>Finding</h2></section></div></article><section class="flow-retained"><h3>Earlier records</h3><section class="phaseReader"><article class="compactRecord"><details class="recordDetails"><summary>Details</summary><div><p>Exact retained provenance.</p><a href="/synthetic-original">Original</a></div></details><div class="recordBody"><h1>Exact retained record</h1><p>Exact source words.</p></div></article></section></section></section>');try{b.d.body.classList.add('wbf-on');const style=b.d.createElement('style');style.textContent='.flow-retained{display:none}.recordDetails{position:absolute}'+fs.readFileSync(new URL('../public/document-study/research-standard.css',import.meta.url),'utf8');b.d.head.append(style);const retained=b.d.querySelector('.flow-retained'),record=b.d.querySelector('.compactRecord'),words=record.querySelector('.recordBody'),metadata=record.querySelector('.recordDetails'),origin=metadata.querySelector('p');assert.equal(metadata.tagName,'SECTION');assert.equal(metadata.querySelectorAll('details,summary').length,0);assert.equal(b.w.getComputedStyle(retained).display,'none');b.d.querySelector('[data-wb-research-record]').click();assert.equal(b.w.getComputedStyle(retained).display,'block');assert.equal(b.w.getComputedStyle(metadata).position,'static');assert.equal(record.querySelector('.recordBody'),words);assert.equal(metadata.querySelector('p'),origin);assert.equal(origin.textContent,'Exact retained provenance.');b.d.querySelector('.wb-research-back').click();assert.equal(b.w.getComputedStyle(retained).display,'none');assert.equal(record.querySelector('.recordBody'),words);}finally{b.close();}
});
